-- ==========================================================
-- Zubair Mobile - Seed 239 Side Key Items
-- Idempotent Batch Insert (on conflict slug do update)
-- ==========================================================

-- 1. Ensure Category Exists
VALUES ('Side Keys', 'side-keys', 'Original mobile power and volume side key buttons for Samsung, Vivo, Infinix, Oppo, Tecno, Redmi, and Itel.')
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name;

-- 2. Insert / Update Products
ON CONFLICT (slug) DO UPDATE SET
  name = EXCLUDED.name,
  price = EXCLUDED.price,
  stock_quantity = EXCLUDED.stock_quantity,
  short_description = EXCLUDED.short_description,
  is_active = true;
